## `/app/hdl/chisel/src/common/IndexAllocator.scala`
```scala
package common
import chisel3._
import chisel3.util._

abstract class IndexAllocator(capacity: Int) extends Module {
  val io = IO(new Bundle {
    val alloc = Decoupled(UInt(log2Ceil(capacity).W))
    val free  = Flipped(Valid(UInt(log2Ceil(capacity).W)))
  })
}

class IndexAllocatorShifting(capacity: Int) extends IndexAllocator(capacity) {
  val used = RegInit(0.U(capacity.W))

  // Find first free slot
  val freeSlot = PriorityEncoder(~used)
  val anyFree = (~used).orR

  io.alloc.valid := anyFree
  io.alloc.bits  := freeSlot

  when(io.alloc.fire) {
    used := used | (1.U << freeSlot)
  }
  when(io.free.valid) {
    used := used & ~(1.U << io.free.bits)
  }
}
```

## `/app/hdl/chisel/src/common/CoralNPUArbiter.scala`
```scala
package common
import chisel3._
import chisel3.util._

class CoralNPURRArbiter[T <: Data](gen: T, n: Int) extends Module {
  val io = IO(new Bundle {
    val in     = Vec(n, Flipped(Decoupled(gen)))
    val out    = Decoupled(gen)
    val chosen = Output(UInt(log2Ceil(n).W))
  })

  val priority = RegInit(0.U(log2Ceil(n).W))

  // Round-robin: start from priority, find first valid
  val chosen = Wire(UInt(log2Ceil(n).W))
  val anyValid = io.in.map(_.valid).reduce(_ || _)

  // Priority encoder starting from priority
  val rotated = VecInit((0 until n).map(i => io.in((i.U + priority) % n.U).valid))
  val rotatedChosen = PriorityEncoder(rotated)
  chosen := (rotatedChosen + priority) % n.U

  io.chosen := chosen
  io.out.valid := anyValid
  io.out.bits  := io.in(chosen).bits

  for (i <- 0 until n) {
    io.in(i).ready := io.out.ready && chosen === i.U && anyValid
  }

  when(io.out.fire) {
    priority := (chosen + 1.U) % n.U
  }
}
```

