// Zip32: interleave two sz-word values
// sz=4 (word), sz=2 (half), sz=1 (byte)
object Zip32 {
  def apply(sz: Int, a: UInt, b: UInt): UInt = {
    val result = Wire(UInt(64.W))
    val chunks = 32 / (sz * 8)
    val chunkBits = sz * 8
    val parts = (0 until chunks).map { i =>
